# hypothesis: even side-length rings -> fill interior with 2, odd -> 7
def solve(g,bg):
    H,W=len(g),len(g[0]); out=[r[:] for r in g]
    for c,cs in comps(g,bg):
        ys=[y for y,_ in cs]; xs=[x for _,x in cs]
        h=max(ys)-min(ys)+1; w=max(xs)-min(xs)+1
        if h==w and len(cs)==4*(h-1):  # hollow square ring
            i0=min(ys); j0=min(xs)
            for y in range(i0+1,i0+h-1):
                for x in range(j0+1,j0+w-1):
                    out[y][x]= 2 if h%2==0 else 7
    return out
